syntax:
template <class Container> class back_insert_iterator {
public:
    explicit back_insert_iterator(Container& c);
    back_insert_iterator& operator=(const typename Container::value_type& value);
    back_insert_iterator& operator*();
    back_insert_iterator& operator++();
    back_insert_iterator& operator++(int);
};

code_example:
#include <vector>
#include <algorithm>
#include <iterator>
#include <iostream>

int main() {
    std::vector<int> numbers = {1, 2, 3};
    // Create a back_insert_iterator for the vector
    auto inserter = std::back_inserter(numbers);
    // Use the iterator with an algorithm to append elements
    std::copy({4, 5, 6}, inserter);
    // Output the contents of the vector
    for (int num : numbers) {
        std::cout << num << ' ';
    }
    return 0;
}
